namespace Arts6311.Domain.Managers.Idempotency;

/// <summary>
/// The committed outcome of one idempotent command, scoped to a subject and an operation. Stores an HMAC fingerprint
/// of the request (never the payload) and the successful result as JSON, for replay until <see cref="ExpiresAt"/>.
/// </summary>
public sealed class IdempotencyRecord
{
    /// <summary>Generated by EF as a sequential GUID when the row is staged.</summary>
    public Guid Id { get; set; }

    /// <summary>
    /// Who the key belongs to: a server-owned handle (<see cref="IdempotentCommand.Subject"/>), never request input.
    /// </summary>
    public string Subject { get; set; } = string.Empty;

    public string Operation { get; set; } = string.Empty;

    public string Key { get; set; } = string.Empty;

    /// <summary>HMAC-SHA256 of the operation and its canonical fingerprint.</summary>
    public byte[] FingerprintHash { get; set; } = [];

    public string ResultJson { get; set; } = string.Empty;

    public DateTimeOffset CreatedAt { get; set; }

    public DateTimeOffset ExpiresAt { get; set; }
}
